/bin/bash -lc "python3 -c \"
import json,hashlib,os,re
d=json.load(open('results.json'))
print([k for k in d])
for k,v in d.items():
  if k"'!='"'cases': print(k, json.dumps(v)[:1500])
def walk(o,acc):
  if isinstance(o,dict):
    if 'path' in o and 'sha256' in o: acc.append((o['path'],o['sha256']))
    for v in o.values(): walk(v,acc)
  elif isinstance(o,list):
    for v in o: walk(v,acc)
acc=[];walk(d,acc)
bad=0
for p,s in acc:
  if not os.path.exists(p): print('MISSING',p); bad+=1; continue
  h=hashlib.sha256(open(p,'rb').read()).hexdigest()
  if h"'!=s: print('"'MISMATCH',p,s,h); bad+=1
print(len(acc),'refs',bad,'bad')
for c in d['cases']:
  ex=c['execution']; print(c['id'],c['disposition'],ex['agent'],ex['run_id'],ex['access_record']['path'], len(c['evidence']), [e['path'].split('/')[1] for e in c['evidence']][:1], set(e['path'].split('/')[1] for e in c['evidence'] if e['path'].startswith('runs/')), [k for k in c if k not in ('id','disposition','summary','candidate_sha256','method','execution','evidence','disposition_record')])
\""

